cd /workspace && python3 << 'PYEOF'
import sqlite3, json

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

# Fix flights with premium_economy/first in prices - strip those keys from cabin_prices_json and dates_json
valid_cabins = {"economy", "business", "basic_economy"}

for row in cur.execute("SELECT flight_id, cabin_prices_json, dates_json FROM flights WHERE source_skill='tau2Airline'").fetchall():
    fid = row["flight_id"]

    # Fix cabin_prices_json
    prices = json.loads(row["cabin_prices_json"] or "{}")
    clean_prices = {k: v for k, v in prices.items() if k in valid_cabins}

    # Fix dates_json 
    dates = json.loads(row["dates_json"] or "{}")
    for date_key, date_val in dates.items():
        if "prices" in date_val:
            date_val["prices"] = {k: v for k, v in date_val["prices"].items() if k in valid_cabins}
        if "available_seats" in date_val:
            date_val["available_seats"] = {k: v for k, v in date_val["available_seats"].items() if k in valid_cabins}

    cur.execute("UPDATE flights SET cabin_prices_json=?, dates_json=? WHERE flight_id=?",
                (json.dumps(clean_prices), json.dumps(dates), fid))

# Fix flight with None departure/arrival time
cur.execute("UPDATE flights SET departure_time=COALESCE(departure_time, ''), arrival_time=COALESCE(arrival_time, '') WHERE source_skill='tau2Airline'")

# Fix passengers missing dob
for row in cur.execute("SELECT booking_id, passengers_json FROM flight_bookings WHERE source_skill='tau2Airline'").fetchall():
    passengers = json.loads(row["passengers_json"] or "[]")
    changed = False
    for p in passengers:
        if "dob" not in p:
            p["dob"] = p.get("date_of_birth", "1990-01-01")
            changed = True
    if changed:
        cur.execute("UPDATE flight_bookings SET passengers_json=? WHERE booking_id=?",
                     (json.dumps(passengers), row["booking_id"]))

conn.commit()
conn.close()
print("DB cleaned successfully")
PYEOF

